create function pg_temp.boundary(delta interval)returns jsonb language plpgsql as $$begin update public.class_sessions set starts_at=statement_timestamp()+interval '2 hours'+delta,ends_at=statement_timestamp()+interval '3 hours'+delta,session_date=((statement_timestamp()+interval '2 hours'+delta)at time zone 'Asia/Kolkata')::date where id=pg_temp.u(700);return pg_temp.run($q$select to_jsonb(b)from public.cancel_class_booking((select(v->>'booking_id')::uuid from h74_res where k='first'))b$q$,pg_temp.mc());end$$;
