select ok(not exists(select 1 from h74_generated where session_date=(statement_timestamp()at time zone 'Asia/Kolkata')::date+7),'CLS holiday skipped');
select ok(not exists(select 1 from h74_generated where session_date<(statement_timestamp()at time zone 'Asia/Kolkata')::date or session_date>(statement_timestamp()at time zone 'Asia/Kolkata')::date+27 or starts_at<=statement_timestamp()or session_date<>(starts_at at time zone 'Asia/Kolkata')::date or (starts_at at time zone 'Asia/Kolkata')::time<>time '23:59'),'CLS horizon local dates and future only');
select is(pg_temp.run('select to_jsonb(app.generate_class_sessions(pg_temp.u(1)))','','service_role'),'0'::jsonb,'CLS generator replay no duplicates');
select is(pg_temp.run($q$select to_jsonb(app.generate_class_sessions(pg_temp.u(1)))$q$,pg_temp.sc(),'authenticated')->>'error','42501','CLS generator authenticated grant blocked');
insert into public.class_bookings(tenant_id,session_id,member_id,status,cancelled_at)select pg_temp.u(1),id,pg_temp.u(109),'cancelled_by_member',now()from public.class_sessions where tenant_id=pg_temp.u(1)and rule_id is not null and session_date=(statement_timestamp()at time zone 'Asia/Kolkata')::date+8;
insert into public.organization_holidays(tenant_id,holiday_on,name)values(pg_temp.u(1),(statement_timestamp()at time zone 'Asia/Kolkata')::date+8,'Protected history'),(pg_temp.u(1),(statement_timestamp()at time zone 'Asia/Kolkata')::date+9,'Prune empty');
do $$begin perform app.generate_class_sessions(pg_temp.u(1));end$$;
select is((select count(*)from public.class_sessions where tenant_id=pg_temp.u(1)and rule_id is not null and session_date=(statement_timestamp()at time zone 'Asia/Kolkata')::date+8),1::bigint,'CLS cancelled booking history protects holiday session');
select is((select count(*)from public.class_sessions where tenant_id=pg_temp.u(1)and rule_id is not null and session_date=(statement_timestamp()at time zone 'Asia/Kolkata')::date+9),0::bigint,'CLS empty derived holiday session pruned');
select is(pg_temp.run($q$update public.class_rules set weekday=(weekday+1)%7 where tenant_id=pg_temp.u(1)returning to_jsonb(id)$q$,'','service_role')->>'error','23514','CLS direct rule identity immutable');
insert into h74_res values('editbook',pg_temp.run($q$select to_jsonb(b)from public.book_class_session(pg_temp.u(704))b$q$,pg_temp.mc(101)));
insert into h74_res values('editbook2',pg_temp.run($q$select to_jsonb(b)from public.book_class_session(pg_temp.u(704))b$q$,pg_temp.mc()));
select is(pg_temp.run($q$select to_jsonb(public.update_class_session(pg_temp.u(704),((statement_timestamp()+interval '1 day')at time zone 'Asia/Kolkata')::date,((statement_timestamp()+interval '1 day 5 minutes')at time zone 'Asia/Kolkata')::time,60,5,pg_temp.u(204)))$q$,pg_temp.sc(),'authenticated')->>'error','GL112','CLS booked time change refused');
insert into h74_res values('capacity',pg_temp.run($q$select to_jsonb(public.update_class_session(pg_temp.u(704),((statement_timestamp()+interval '1 day')at time zone 'Asia/Kolkata')::date,((select starts_at from public.class_sessions where id=pg_temp.u(704))at time zone 'Asia/Kolkata')::time,60,1,pg_temp.u(204)))$q$,pg_temp.sc()));
select ok((select v->>'error'is null from h74_res where k='capacity')and(select capacity=1 and customised_at is not null from public.class_sessions where id=pg_temp.u(704)),'CLS capacity edit detaches without losing booking');
select is((select count(*)from public.class_bookings where session_id=pg_temp.u(704)and status='booked'),2::bigint,'CLS capacity below holdings preserves both seats');
select is(pg_temp.run($q$select to_jsonb(b)from public.book_class_session(pg_temp.u(704))b$q$,pg_temp.mc(109))->>'error','GL090','CLS lowered capacity refuses further booking');
insert into h74_res values('read',pg_temp.run($q$select coalesce(jsonb_agg(to_jsonb(r)),'[]')from public.read_member_class_schedule(current_date-1,current_date+4)r$q$,pg_temp.mc(101)));
select ok(not exists(select 1 from h74_res where k='read'and(v::text like '%CLS PRIVATE%'or v::text like '%+919749%'or v::text like '%'||pg_temp.u(100)::text||'%')),'CLS member read no other identity');
select ok(not exists(select 1 from (select v from h74_res where k='read')x cross join lateral jsonb_array_elements(x.v)r cross join lateral jsonb_object_keys(r)k where k not in('session_id','service_id','service_name','service_description','branch_id','branch_name','timezone','session_date','starts_at','ends_at','trainer_name','capacity','booked_count','spots_left','session_status','my_booking_id','my_booking_status','availability','can_cancel','cancel_by')),'CLS member read exact safe column set');
select is(pg_temp.run($q$select to_jsonb(r)from public.create_class_rules(pg_temp.u(600),pg_temp.u(11),array[1,1]::smallint[],time '12:00',60,2,null,null,null)r$q$)->>'error','22023','CLS duplicate weekday list refused before writes');
select is(pg_temp.run($q$select to_jsonb(r)from public.create_class_rules(pg_temp.u(600),pg_temp.u(11),array[1]::smallint[],time '12:00',60,2,pg_temp.u(203),null,null)r$q$)->>'error','22023','CLS desk cannot be assigned trainer');
create temp table h74_protected as select s.id,s.rule_id from public.class_sessions s where s.tenant_id=pg_temp.u(1)and s.rule_id is not null and s.session_date=(statement_timestamp()at time zone 'Asia/Kolkata')::date+8;
grant select on h74_protected to authenticated;
insert into h74_res values('endrule',pg_temp.run($q$select to_jsonb(r)from public.update_class_rule((select rule_id from h74_protected),60,2,pg_temp.u(204),null,false)r$q$));
select ok((select v->>'error'is null and(v->>'sessions_kept')::int>=1 from h74_res where k='endrule'),'CLS rule deactivation reports booking-history kept');
select ok(exists(select 1 from public.class_sessions s join h74_protected p on s.id=p.id where s.status='scheduled'),'CLS rule deactivation retains cancelled-member booking history');
select ok(not exists(select 1 from public.class_sessions s join h74_protected p on s.rule_id=p.rule_id where s.starts_at>statement_timestamp()and s.customised_at is null and s.id<>p.id),'CLS inactive rule removes only empty future occurrences');
insert into h74_res values('disable',pg_temp.run($q$select to_jsonb(public.set_service_active(pg_temp.u(600),false))$q$,pg_temp.sc()));
select is(pg_temp.run($q$select to_jsonb(b)from public.book_class_session(pg_temp.u(702))b$q$,pg_temp.mc(101),'authenticated')->>'error','GL092','CLS disabled service prevents new booking');
select ok(exists(select 1 from public.class_bookings where session_id=pg_temp.u(704)and status='booked'),'CLS disable preserves commitments');
select is(pg_temp.run('select to_jsonb(count(*))from public.read_member_class_schedule(current_date-1,current_date+4)',pg_temp.mc(102)),'0'::jsonb,'CLS disabled hidden from unbooked member');
select ok((select count(*)from public.attendance where tenant_id in(pg_temp.u(1),pg_temp.u(2)))=0 and(select count(*)from public.no_show_cases where tenant_id in(pg_temp.u(1),pg_temp.u(2)))=0 and not exists(select 1 from h74_original),'CLS booking cancel marking never create attendance or cases');
select is(pg_temp.run($q$select to_jsonb(r)from public.read_member_class_schedule(null,current_date)r$q$,pg_temp.mc(),'authenticated')->>'error','22023','CLS malformed member read window');
select is(pg_temp.run($q$select to_jsonb(r)from public.read_member_class_schedule(current_date,current_date+31)r$q$,pg_temp.mc(),'authenticated')->>'error','22023','CLS malformed member read window');
